const all = $input.all().map(i => i.json);
const batchSize = $('Globals').first().json.BATCH_SIZE || 1;
const pending = all.filter(r => r.status === 'pending');
if (pending.length === 0) {
  return [{ json: { _empty: true } }];
}
const batch = pending.slice(0, batchSize);
return batch.map(r => ({ json: r }));

const raw = $json.text || $json.data || '';
let pages = [];
if (Array.isArray(raw)) pages = raw;
else if (typeof raw === 'string') {
  pages = raw.split('\f');
  if (pages.length < 3) pages = raw.split(/\n\s*\n\s*\n/);
}
// Cap to 30k chars to stay friendly with the model context
const paperText = pages.join('\n\n').slice(0, 30000);
const ctx = $('Loop Over Papers').item.json;
return [{ json: { ...ctx, paper_text: paperText, paper_total_pages: pages.length } }];

// ============================================================================
//  Parse Concept  —  paste into the "Parse Concept" Code node.
//  Now accepts a VARIABLE number of slides (5-10) instead of a fixed count,
//  and renumbers them so the "n/total" counter is always correct.
// ============================================================================

const raw = $json.output || '';
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Carousel concept invalid JSON: ' + e.message + ' | raw: ' + raw.slice(0, 300));
}

// Allowed slide-count range — change these two numbers to widen/narrow it.
const MIN_SLIDES = 5;
const MAX_SLIDES = 10;

const slides = Array.isArray(parsed.slides) ? parsed.slides : [];
if (slides.length < MIN_SLIDES || slides.length > MAX_SLIDES) {
  throw new Error(`Expected ${MIN_SLIDES}-${MAX_SLIDES} slides, got ${slides.length}`);
}
if (slides[0]?.slide_type !== 'hook' || slides[slides.length - 1]?.slide_type !== 'cta') {
  throw new Error('First slide must be "hook" and last must be "cta"');
}

// Renumber sequentially so the n/total counter never drifts from the model output.
const normalized = slides.map((s, i) => ({
  slide_number: i + 1,
  slide_type: s.slide_type,
  headline: s.headline,
  body: s.body,
  accent: s.accent || '',
}));

const ctx = $('Build Paper Text').item.json;
return [{
  json: {
    drive_file_id: ctx.drive_file_id,
    drive_file_name: ctx.drive_file_name,
    title: ctx.title,
    authors: ctx.authors,
    field: ctx.field,
    content_hook: parsed.content_hook || '',
    content_brief: parsed.content_brief || '',
    slides: normalized,
    caption: parsed.caption || '',
    hashtags: parsed.hashtags || [],
    total_slides: normalized.length,
  },
}];

const parent = $json;
const g = $('Globals').first().json;
const total = parent.total_slides;

const ASSET = g.ASSET_BASE_URL || 'http://localhost:3000/assets';
const LOGO_LIGHT = g.LOGO_URL || '';            // dark logo  -> used on light slides
const LOGO_NEG = g.LOGO_URL_NEGATIVE || '';      // white logo -> used on dark/red slides

// Slide types that sit on a dark or red background (need the white/negative logo).
const DARK_TYPES = ['hook', 'cta', 'payoff'];

// Small "eyebrow" label per slide type. Set to '' to hide. Edit freely.
const KICKER = {
  hook: '',
  stakes: 'The catch',
  setup: 'The question',
  concept: 'How it works',
  payoff: 'The finding',
  relevance: 'Why it matters',
  cta: 'Your turn',
};

// Slide types that show a "Swipe →" nudge (the ones that must earn the next swipe).
const SWIPE_HINT = ['hook', 'stakes'];

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function withAccent(text, accent) {
  const e = esc(text);
  if (!accent) return e;
  const a = esc(accent);
  const idx = e.toLowerCase().indexOf(a.toLowerCase());
  if (idx === -1) return e;
  return e.slice(0, idx) + '<span class="accent">' + e.slice(idx, idx + a.length) + '</span>' + e.slice(idx + a.length);
}

function logoMarkup(slideType) {
  const isDark = DARK_TYPES.includes(slideType);
  const src = isDark ? LOGO_NEG : LOGO_LIGHT;
  if (src) return `<img class="logo-img" src="${esc(src)}" alt="TU/e">`;
  return `<span class="logo-ph">TU/e logo</span>`;
}

const slidesHtml = parent.slides.map((s) => {
  const kicker = KICKER[s.slide_type] || '';
  const showSwipe = SWIPE_HINT.includes(s.slide_type);
  return `
  <div class="slide slide--${esc(s.slide_type)}">
    <div class="top">
      <span class="progress">${s.slide_number}/${total}</span>
      ${kicker ? `<span class="kicker">${esc(kicker)}</span>` : ''}
    </div>
    <div class="content">
      <h1 class="headline">${withAccent(s.headline, s.accent)}</h1>
      <p class="body">${esc(s.body)}</p>
    </div>
    <div class="footer">
      <span class="handle">${esc(g.FACULTY_NAME)}</span>
      <div class="footer-right">
        ${showSwipe ? `<span class="swipe">Swipe &rarr;</span>` : ''}
        <div class="logo">${logoMarkup(s.slide_type)}</div>
      </div>
    </div>
  </div>`;
}).join('\n');

const html = `<!doctype html>
<html><head><meta charset="utf-8"><style>
  /* ---- custom fonts: files live in carousel-renderer/assets/fonts/ ---- */
  @font-face { font-family:'Gilroy'; src:url('${ASSET}/fonts/Gilroy-Bold.woff2') format('woff2'); font-weight:700; font-display:swap; }
  @font-face { font-family:'Gilroy'; src:url('${ASSET}/fonts/Gilroy-ExtraBold.woff2') format('woff2'); font-weight:800; font-display:swap; }
  @font-face { font-family:'Lato'; src:url('${ASSET}/fonts/Lato-Regular.woff2') format('woff2'); font-weight:400; font-display:swap; }
  @font-face { font-family:'Lato'; src:url('${ASSET}/fonts/Lato-Bold.woff2') format('woff2'); font-weight:700; font-display:swap; }

  /* ---- shared TU/e tokens: the one style every slide belongs to ---- */
  :root {
    --bg: #ffffff;
    --fg: #000000;
    --muted: #666666;
    --accent: #c72125;
    --font-display: 'Gilroy', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
    --font-body: 'Lato', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  .slide {
    width: ${g.SLIDE_WIDTH}px;
    height: ${g.SLIDE_HEIGHT}px;
    background: var(--bg);
    color: var(--fg);
    padding: 96px 84px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    position: relative;
    overflow: hidden;
    font-family: var(--font-body);
  }
  .top { display: flex; justify-content: space-between; align-items: baseline; }
  .progress { font-size: 28px; font-weight: 700; color: var(--muted); }
  .kicker { font-family: var(--font-display); font-size: 28px; font-weight: 700; letter-spacing: 0.02em; color: var(--accent); }
  .content { flex: 1; display: flex; flex-direction: column; justify-content: center; }
  .headline { font-family: var(--font-display); font-size: 84px; line-height: 1.04; font-weight: 800; letter-spacing: -0.01em; }
  .headline::before { content: ''; display: block; width: 76px; height: 12px; background: var(--accent); margin-bottom: 30px; }
  .body { font-size: 34px; line-height: 1.35; margin-top: 30px; color: var(--muted); }
  .footer { display: flex; justify-content: space-between; align-items: center; }
  .handle { font-size: 26px; color: var(--muted); }
  .footer-right { display: flex; align-items: center; gap: 28px; }
  .swipe { font-family: var(--font-display); font-weight: 700; font-size: 26px; color: var(--accent); }
  .logo { height: 60px; display: flex; align-items: center; }
  .logo-img { height: 100%; width: auto; display: block; }
  .logo-ph { display: inline-flex; align-items: center; height: 60px; padding: 0 22px; border: 2px dashed currentColor; color: var(--muted); opacity: 0.65; font-size: 24px; }
  .accent { color: var(--accent); }

  /* ---- per-type variants: same system, just a few tokens remapped ---- */
  .slide--hook, .slide--cta { --bg: #000000; --fg: #ffffff; --muted: #898b8c; }
  .slide--hook .headline { font-size: 102px; }
  .slide--stakes .headline { font-size: 92px; }
  .slide--payoff { --bg: #c72125; --fg: #ffffff; --muted: #f4cccd; --accent: #ffffff; }
  .slide--payoff .accent { text-decoration: underline; text-decoration-thickness: 7px; text-underline-offset: 10px; }
  .slide--relevance { --bg: #eaeaea; --muted: #555555; }
</style></head><body>
${slidesHtml}
</body></html>`;

return [{
  json: {
    _parent: { ...parent, slides: undefined },
    slides: parent.slides.map((s) => ({ slide_number: s.slide_number, slide_type: s.slide_type })),
    total_slides: total,
    html,
  },
}];

const resp = $json;
const build = $('Build Carousel HTML').first().json;
const parent = build._parent;
const meta = build.slides || [];
const images = resp.images || [];

if (images.length !== meta.length) {
  throw new Error(`Renderer returned ${images.length} images but expected ${meta.length}`);
}

const out = [];
for (let i = 0; i < meta.length; i++) {
  const m = meta[i];
  const img = images[i];
  const b64 = typeof img === 'string' ? img : (img.image_base64 || img.base64 || img.data);
  if (!b64) throw new Error('No image data for slide ' + m.slide_number);
  const buffer = Buffer.from(b64, 'base64');
  const binaryData = await this.helpers.prepareBinaryData(buffer, `slide_${m.slide_number}.png`, 'image/png');
  out.push({
    json: { _parent: parent, slide_number: m.slide_number, slide_type: m.slide_type },
    binary: { data: binaryData }
  });
}
return out;

const prev = $('Split Render Output').item.json;
const driveResp = $json;
return {
  json: {
    _parent: prev._parent,
    slide_number: prev.slide_number,
    slide_type: prev.slide_type,
    drive_file_id: driveResp.id,
    drive_view_link: `https://drive.google.com/file/d/${driveResp.id}/view`
  }
};

const arr = ($json.slide_number || []).map((n, i) => ({
  slide_number: n,
  slide_type: $json.slide_type[i],
  drive_file_id: $json.drive_file_id[i],
  drive_view_link: $json.drive_view_link[i]
}));
arr.sort((a, b) => a.slide_number - b.slide_number);

const parent = $items('Capture Slide Ref')[0].json._parent;

return [{
  json: {
    drive_file_id: parent.drive_file_id,
    title: parent.title,
    content_hook: parent.content_hook,
    content_brief: parent.content_brief,
    slide_urls: arr.map(s => s.drive_view_link).join('\n'),
    drive_backup_links: arr.map(s => s.drive_view_link).join('\n'),
    caption: parent.caption,
    hashtags: (parent.hashtags || []).join(' '),
    generated_at: new Date().toISOString(),
    status: 'generated'
  }
}];
